WITH recent_subscriptions AS (SELECT *, UPPER(plan) AS plan_upper FROM subscriptions WHERE MONTH(start_date) IN (1, 6, 12) AND customer_id = 24 AND monthly_fee >= 190), status_summary AS (SELECT status, CASE WHEN monthly_fee >= 204 THEN 'high' WHEN monthly_fee >= 76 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, MIN(monthly_fee) AS min_monthly_fee FROM recent_subscriptions GROUP BY status, CASE WHEN monthly_fee >= 204 THEN 'high' WHEN monthly_fee >= 76 THEN 'mid' ELSE 'low' END) SELECT status, monthly_fee_bucket, min_monthly_fee FROM status_summary ORDER BY min_monthly_fee ASC
